package com.asmj.marketplace.analytics.controller;
import com.asmj.marketplace.analytics.service.AnalyticsService;import com.asmj.marketplace.common.response.ApiResponse;import com.asmj.marketplace.vendor.service.VendorService;import lombok.RequiredArgsConstructor;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.Authentication;import java.util.*;
@RestController @RequestMapping("/api/analytics") @RequiredArgsConstructor public class AnalyticsController{private final AnalyticsService s;private final VendorService vendors;@GetMapping("/admin")@org.springframework.security.access.prepost.PreAuthorize("hasRole('ADMIN')")public ApiResponse<Map<String,Object>> admin(){return ApiResponse.ok("Analytics",s.summary());}@GetMapping("/vendor")@org.springframework.security.access.prepost.PreAuthorize("hasRole('VENDOR')")public ApiResponse<Map<String,Object>> vendor(Authentication a){return ApiResponse.ok("Vendor analytics",s.vendorSummary(vendors.me(a.getName()).getId()));}}